template<typename T>
void perfect_forwarder(T&& arg) { // Universal Reference syntax
    // T&& is an lvalue reference OR rvalue reference
    // depending on template argument deduction (T)
    target(std::forward<T>(arg));
}

// Result of Template Deduction (T&& binds to input type)
// Input L-value (Type A&): T is deduced as A& -> T&& collapses to A&
// Input R-value (Type A):  T is deduced as A  -> T&& collapses to A&&

struct Widget { explicit Widget(int) {} };
std::vector<Widget> v;

// Emplacement uses perfect forwarding (variadic templates)
v.emplace_back(10);          // Uses R-value path (move)

Widget w(5);
v.emplace_back(w);           // Uses L-value path (copy)
// Signature: template<typename... Args> void emplace(Args&&... args)
// Internal construction: std::forward<Args>(args)...
